INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > Thermotransferdrucker
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Thermotransferdrucker unabhängig von den Etikettenmaterialien ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Drucker müssen mit Material und Farbband kompatibel sein"}, {"text": "Ja", "correct": false, "because": "Material bestimmt Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines Thermotransferdruckers immer die Haltbarkeitsanforderungen der Etiketten berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Haltbarkeit ist ein Hauptmerkmal"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines Thermotransferdruckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Effizienz hängt davon ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Thermotransferdrucker ohne Rücksicht auf die Verbrauchsmaterialien ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Farbbänder sind essenziell"}, {"text": "Ja", "correct": false, "because": "Materialien sind zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Thermotransferdrucker immer teurer als Direktthermodrucker?', 2, '[{"text": "Ja", "correct": true, "because": "Zusätzliche Farbbänder erhöhen Kosten"}, {"text": "Nein", "correct": false, "because": "Preisunterschied ist üblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines Thermotransferdruckers am wichtigsten?', 3, '[{"text": "Nutzungsanforderungen", "correct": true, "because": "Bestimmen Material und Qualität"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für Thermotransferdrucker essenziell?', 2, '[{"text": "Farbband", "correct": true, "because": "Überträgt Farbe aufs Etikett"}, {"text": "Toner", "correct": false, "because": "Für Laserdrucker"}, {"text": "Tintenpatrone", "correct": false, "because": "Für Tintenstrahldrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstelle wird für moderne Thermotransferdrucker am häufigsten verwendet?', 2, '[{"text": "USB", "correct": true, "because": "Universeller Standard"}, {"text": "Parallelport", "correct": false, "because": "Veraltet"}, {"text": "Serial", "correct": false, "because": "Weniger gebräuchlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung ist typisch für Thermotransferdrucker?', 3, '[{"text": "Etikettendruck", "correct": true, "because": "Für langlebige Etiketten geeignet"}, {"text": "Fotodruck", "correct": false, "because": "Andere Drucker besser"}, {"text": "Durchschlagdruck", "correct": false, "because": "Falsche Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Thermotransferdruckern?', 2, '[{"text": "Langlebige Etiketten", "correct": true, "because": "Widerstandsfähig gegen Umwelt"}, {"text": "Geringe Kosten", "correct": false, "because": "Farbbänder erhöhen Kosten"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Nicht primärer Vorteil"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines Thermotransferdruckers?', 4, '[{"text": "Etikettenmaterial", "correct": true, "because": "Bestimmt Kompatibilität"}, {"text": "Druckauflösung", "correct": true, "because": "Beeinflusst Lesbarkeit"}, {"text": "Druckgeschwindigkeit", "correct": true, "because": "Wichtig für Volumen"}, {"text": "Gewicht des Druckers", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Thermotransferdrucker?', 3, '[{"text": "Haltbare Etiketten", "correct": true, "because": "Widerstandsfähig gegen Abnutzung"}, {"text": "Hohe Druckqualität", "correct": true, "because": "Präzise und klar"}, {"text": "Vielseitigkeit", "correct": true, "because": "Verschiedene Materialien möglich"}, {"text": "Geringere Betriebskosten", "correct": false, "because": "Farbbänder erhöhen Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines Thermotransferdruckers auftreten?', 3, '[{"text": "Inkompatibilität mit Materialien", "correct": true, "because": "Falsches Material unbrauchbar"}, {"text": "Unzureichende Auflösung", "correct": true, "because": "Unleserliche Etiketten"}, {"text": "Hohe Verbrauchskosten", "correct": true, "because": "Farbbänder teuer"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können Thermotransferdrucker unterstützen?', 4, '[{"text": "USB", "correct": true, "because": "Standardverbindung"}, {"text": "Ethernet", "correct": true, "because": "Für Netzwerkzugriff"}, {"text": "Bluetooth", "correct": true, "because": "Drahtlose Option"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von Thermotransferdruckern?', 3, '[{"text": "Logistik", "correct": true, "because": "Langlebige Versandetiketten"}, {"text": "Einzelhandel", "correct": true, "because": "Robuste Preisschilder"}, {"text": "Produktion", "correct": true, "because": "Widerstandsfähige Kennzeichnungen"}, {"text": "Fotodruck", "correct": false, "because": "Andere Drucker besser"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Thermotransferdrucker verwenden Farbbänder. b) Sie sind für kurzlebige Etiketten besser geeignet als Direktthermodrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Farbbänder ja, langlebig besser"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Thermotransferdrucker bieten hohe Druckqualität. b) Ihre Druckgeschwindigkeit ist immer geringer als die von Tintenstrahldruckern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Geschwindigkeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Thermotransferdrucker sind für Logistik-Etiketten geeignet. b) Sie benötigen keine speziellen Materialien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logistik ja, spezielle Materialien nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Netzwerkfähigkeit ist bei Thermotransferdruckern nützlich. b) Sie sind für den Fotodruck optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ja, Fotodruck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Thermotransferdrucker sind teurer als Direktthermodrucker. b) Ihre Etiketten sind weniger haltbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Teurer ja, haltbarer nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

